// Des: Tests for keepalive: every vendor, failover feed, verify, requeue
// Flo: two mock clouds as vendors v1 v2 and q1 q2 > run at shifted clocks > assert flags, failover state, pack rows, outbox
// I/O: mock clouds + temp db > pass or fail (no leaks)
// Run: zig build test
// ===================================================================
const std = @import("std"); const keep = @import("ru-keep-live.zig"); const sync = @import("sy-clou-sync.zig"); const cmok = @import("sy-clou-mock.zig"); const outb = @import("sy-clou-outb.zig"); const inde = @import("st-page-inde.zig"); const sqli = @import("st-stor-sqli.zig"); const pack = @import("ru-purg-pack.zig"); const file = @import("st-stor-file.zig"); const hash = @import("ut-hash-dedu.zig"); const fail = @import("ru-fail-over.zig"); const civi = @import("ut-date-civi.zig");
const allo = std.testing.allocator;
const NOWZ: i64 = 1795528470301;
const DAYZ: i64 = 86400000;
const Rigg = struct { tmpz: std.testing.TmpDir, cld1: cmok.Mock, cld2: cmok.Mock, dirz: []u8, rawd: []u8, dbzz: sqli.Dbzz, aren: std.heap.ArenaAllocator, synz: sync.Sync, pool: [2]sync.Vsto, sqls: [2]sync.Vsql, nume: u32 = 0,
pub fn upzz(self: *Rigg) !void { self.tmpz = std.testing.tmpDir(.{}); self.dirz = try std.fmt.allocPrint(allo, ".zig-cache/tmp/{s}", .{self.tmpz.sub_path}); self.rawd = try std.fs.path.join(allo, &.{ self.dirz, "raw" }); self.dbzz = try inde.pageOpen(allo, std.testing.io, self.dirz); self.aren = std.heap.ArenaAllocator.init(allo); self.cld1 = cmok.Mock.init(allo); self.cld2 = cmok.Mock.init(allo); self.nume = 0; self.pool = .{ .{ .name = "v1", .store = self.cld1.store() }, .{ .name = "v2", .store = self.cld2.store() } }; self.sqls = .{ .{ .name = "q1", .sql2 = self.cld1.sql2() }, .{ .name = "q2", .sql2 = self.cld2.sql2() } }; self.synz = .{ .iozz = std.testing.io, .dbzz = &self.dbzz, .dirz = self.dirz, .conf = .{}, .store = self.cld1.store(), .sql2 = self.cld1.sql2(), .pool = &self.pool, .sqls = &self.sqls }; }
pub fn down(self: *Rigg) void { self.cld1.deinit(); self.cld2.deinit(); self.aren.deinit(); self.dbzz.close(); allo.free(self.rawd); allo.free(self.dirz); self.tmpz.cleanup(); }
pub fn mkpk(self: *Rigg, mock: *cmok.Mock, name: []const u8, vend: []const u8, cont: usize, saveRawz: bool) !void { const aren = self.aren.allocator(); var pars: std.ArrayList(pack.Part) = .empty; for (0..cont) |_| { self.nume += 1; const bodz = try std.fmt.allocPrint(aren, "verify body number {d}", .{self.nume}); if (saveRawz) _ = try file.fileSave(allo, std.testing.io, self.rawd, bodz); try pars.append(aren, .{ .hexz = try aren.dupe(u8, &hash.hashHexz(bodz)), .gzzz = try file.gzipPack(aren, bodz) }); } const byts = try pack.packBuil(aren, pars.items); const ents = try pack.packPars(aren, byts); const stoz = mock.store(); try stoz.put(stoz.ctx2, aren, std.testing.io, name, byts); for (ents) |entr| { var insz = try self.dbzz.prep("INSERT INTO pack(hexz,packk,offs,lenz,vfyz,vend) VALUES(?1,?2,?3,?4,1,?5);"); defer insz.fini(); try insz.bindText(1, entr.hexz); try insz.bindText(2, name); try insz.bindIntz(3, @intCast(entr.offs)); try insz.bindIntz(4, @intCast(entr.lenz)); try insz.bindText(5, vend); _ = try insz.step(); } }
pub fn scal(self: *Rigg, sqlz: [:0]const u8) !i64 { var stmt = try self.dbzz.prep(sqlz); defer stmt.fini(); if (!try stmt.step()) return -1; return stmt.colzIntz(0); } };
test "keepalive touches every store and database once per interval, then waits" { var rig3: Rigg = undefined; try rig3.upzz(); defer rig3.down(); const rsl1 = try keep.liveRunz(&rig3.synz, rig3.aren.allocator(), NOWZ); try std.testing.expect(rsl1.ranz); try std.testing.expectEqual(@as(u32, 4), rsl1.ping); try std.testing.expectEqual(@as(u32, 0), rsl1.pbad); try std.testing.expectEqual(@as(usize, 1), rig3.cld1.sawzStmt("SELECT 1")); try std.testing.expectEqual(@as(usize, 1), rig3.cld2.sawzStmt("SELECT 1")); const rsl2 = try keep.liveRunz(&rig3.synz, rig3.aren.allocator(), NOWZ + 3 * DAYZ); try std.testing.expect(!rsl2.ranz); const rsl3 = try keep.liveRunz(&rig3.synz, rig3.aren.allocator(), NOWZ + 8 * DAYZ); try std.testing.expect(rsl3.ranz); try std.testing.expectEqual(@as(usize, 2), rig3.cld1.sawzStmt("SELECT 1")); }
test "a failing vendor feeds failover: N failed runs skip it, denied skips to next month, healthy ones stay okay" { var rig3: Rigg = undefined; try rig3.upzz(); defer rig3.down(); rig3.synz.conf.clou_fail_runs = 1; rig3.cld2.stoo = true; const rsl1 = try keep.liveRunz(&rig3.synz, rig3.aren.allocator(), NOWZ); try std.testing.expectEqual(@as(u32, 1), rsl1.pbad); try std.testing.expect(!try fail.failOkay(&rig3.dbzz, "v2", NOWZ + 1000)); try std.testing.expect(try fail.failOkay(&rig3.dbzz, "v1", NOWZ + 1000)); try std.testing.expect(try fail.failOkay(&rig3.dbzz, "q2", NOWZ + 1000)); rig3.cld2.stoo = false; rig3.cld2.deny = true; const rsl2 = try keep.liveRunz(&rig3.synz, rig3.aren.allocator(), NOWZ + 8 * DAYZ); try std.testing.expectEqual(@as(u32, 2), rsl2.pbad); try std.testing.expectEqual(civi.civiNext(NOWZ + 8 * DAYZ), try fail.failUnti(&rig3.dbzz, "q2")); rig3.cld2.deny = false; _ = try keep.liveRunz(&rig3.synz, rig3.aren.allocator(), NOWZ + 16 * DAYZ); try std.testing.expect(try fail.failOkay(&rig3.dbzz, "v1", NOWZ + 16 * DAYZ)); }
test "dry run touches nothing" { var rig3: Rigg = undefined; try rig3.upzz(); defer rig3.down(); rig3.synz.dryz = true; const rslt = try keep.liveRunz(&rig3.synz, rig3.aren.allocator(), NOWZ); try std.testing.expect(!rslt.ranz); try std.testing.expectEqual(@as(usize, 0), rig3.cld1.stm2.items.len); const vrzz = try keep.veriRunz(&rig3.synz, rig3.aren.allocator(), NOWZ); try std.testing.expect(!vrzz.ranz); }
test "verify downloads random packs, checks every entry, stamps the time, waits for the interval" { var rig3: Rigg = undefined; try rig3.upzz(); defer rig3.down(); try rig3.mkpk(&rig3.cld1, "runs/20260601T000000Z-a.pack", "v1", 2, false); try rig3.mkpk(&rig3.cld2, "runs/20260602T000000Z-b.pack", "v2", 1, false); const rsl1 = try keep.veriRunz(&rig3.synz, rig3.aren.allocator(), NOWZ); try std.testing.expect(rsl1.ranz); try std.testing.expectEqual(@as(u32, 2), rsl1.veri); try std.testing.expectEqual(@as(u32, 0), rsl1.vbad); try std.testing.expectEqual(@as(i64, 3), try rig3.scal("SELECT count(*) FROM pack WHERE vfyz>1;")); const rsl2 = try keep.veriRunz(&rig3.synz, rig3.aren.allocator(), NOWZ + 3 * DAYZ); try std.testing.expect(!rsl2.ranz); }
test "a corrupt pack with local files is requeued; without local files it is counted as lost; both lose their verified stamp" { var rig3: Rigg = undefined; try rig3.upzz(); defer rig3.down(); try rig3.mkpk(&rig3.cld1, "runs/20260601T000000Z-a.pack", "v1", 2, true); try rig3.mkpk(&rig3.cld1, "runs/20260602T000000Z-b.pack", "v1", 1, false); const stoz = rig3.cld1.store(); try stoz.put(stoz.ctx2, rig3.aren.allocator(), std.testing.io, "runs/20260601T000000Z-a.pack", "SCRAPK1\nbroken"); try stoz.put(stoz.ctx2, rig3.aren.allocator(), std.testing.io, "runs/20260602T000000Z-b.pack", "SCRAPK1\nalso broken"); const rslt = try keep.veriRunz(&rig3.synz, rig3.aren.allocator(), NOWZ); try std.testing.expectEqual(@as(u32, 2), rslt.vbad); try std.testing.expectEqual(@as(u32, 2), rslt.fixd); try std.testing.expectEqual(@as(u32, 1), rslt.lost); try std.testing.expectEqual(@as(i64, 2), try outb.outbCont(&rig3.dbzz, 0)); try std.testing.expectEqual(@as(i64, 0), try rig3.scal("SELECT count(*) FROM pack WHERE vfyz>0;")); }
test "a missing object is treated as a bad pack, not a crash" { var rig3: Rigg = undefined; try rig3.upzz(); defer rig3.down(); try rig3.mkpk(&rig3.cld1, "runs/20260601T000000Z-a.pack", "v1", 1, true); const stoz = rig3.cld1.store(); try stoz.del2(stoz.ctx2, rig3.aren.allocator(), std.testing.io, "runs/20260601T000000Z-a.pack"); const rslt = try keep.veriRunz(&rig3.synz, rig3.aren.allocator(), NOWZ); try std.testing.expectEqual(@as(u32, 1), rslt.vbad); try std.testing.expectEqual(@as(u32, 1), rslt.fixd); }
test "a keep pack whose copy is missing or different is queued for a new copy; a matching copy is fine" { var rig3: Rigg = undefined; try rig3.upzz(); defer rig3.down(); rig3.synz.copy = rig3.cld2.store(); try rig3.mkpk(&rig3.cld1, "keep/20260601T000000Z-k.pack", "v1", 1, false); const rsl1 = try keep.veriRunz(&rig3.synz, rig3.aren.allocator(), NOWZ); try std.testing.expectEqual(@as(u32, 1), rsl1.cops); try std.testing.expectEqual(@as(i64, 1), try outb.outbCont(&rig3.dbzz, 0)); const oldz = rig3.cld1.map.get("keep/20260601T000000Z-k.pack").?; const sto2 = rig3.cld2.store(); try sto2.put(sto2.ctx2, rig3.aren.allocator(), std.testing.io, "keep/20260601T000000Z-k.pack", oldz); const rsl2 = try keep.veriRunz(&rig3.synz, rig3.aren.allocator(), NOWZ + 8 * DAYZ); try std.testing.expectEqual(@as(u32, 0), rsl2.cops); }
test "purg_veri_cont 0 turns verify off" { var rig3: Rigg = undefined; try rig3.upzz(); defer rig3.down(); try rig3.mkpk(&rig3.cld1, "runs/20260601T000000Z-a.pack", "v1", 1, false); rig3.synz.conf.purg_veri_cont = 0; const rslt = try keep.veriRunz(&rig3.synz, rig3.aren.allocator(), NOWZ); try std.testing.expect(!rslt.ranz); try std.testing.expectEqual(@as(i64, 1), try rig3.scal("SELECT count(*) FROM pack WHERE vfyz=1;")); }
